[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$Path)
$ErrorActionPreference='Stop';$d=[IO.Path]::GetFullPath($Path);$x=Get-Content (Join-Path $d 'project-story.json') -Raw|ConvertFrom-Json
if(@($x.offer.versions).Count -lt 3){throw 'PORTABLE_OFFER_VERSIONS_MINITEMS'};if(@($x.pages).Count -ne 19){throw 'PORTABLE_PAGE_COUNT'};if(@($x.tickets).Count -ne 17){throw 'PORTABLE_TICKET_COUNT'};if(@($x.timeline).Count -ne 15){throw 'PORTABLE_TIMELINE_COUNT'};if(@($x.hypercare).Count -ne 3){throw 'PORTABLE_HYPERCARE_COUNT'}
$hours=0;$cost=0;foreach($t in @($x.tickets)){foreach($w in @($t.worklogs)){$hours+=$w.hours;$cost+=$w.cost};foreach($p in @($t.comments)){if($p.type -notin @('working','closing')){throw 'PORTABLE_COMMENT_TYPE'}}};if($hours -ne 80 -or $cost -ne 9600 -or $x.offer.actual_hours -ne $hours -or $x.offer.actual_cost -ne $cost){throw 'PORTABLE_COST_MISMATCH'}
foreach($p in @($x.pages)){if($p.sourcePath -match '(^[A-Za-z]:|^/|\.\.|\\)'){throw 'PORTABLE_UNSAFE_PATH'};$f=Join-Path $d $p.sourcePath;if(-not(Test-Path $f -PathType Leaf)){throw 'PORTABLE_PAGE_MISSING'};$txt=Get-Content $f -Raw;if($txt -notmatch "id:\s*$($p.id)" -or $txt -notmatch "version:\s*$($p.version)" -or $txt -notmatch "status:\s*$($p.status)"){throw 'PORTABLE_PAGE_METADATA'}}
foreach($e in @($x.timeline)){if([datetime]$e.time -lt [datetime]$x.offer.start_time -or [datetime]$e.time -gt [datetime]$x.offer.end_time){throw 'PORTABLE_TIMELINE_RANGE'}};foreach($h in @($x.hypercare)){if($h.status -ne 'closed' -or $h.go_no_go -ne 'GO'){throw 'PORTABLE_HYPERCARE_EXIT'}};Write-Host 'PASS: Portable external project story conformance validated read-only.'
